import{_ as a,a as n,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-4/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册语法总结 · 过去分词作后置定语至独立主格的主语与分词","link":"/life/english/new-concept/book-4/grammar-part-03"},"next":{"text":"第四册：流利英语 · 全册语法总结 · there be 与存在命题至决策段落中的 however、therefore 与条件","link":"/life/english/new-concept/book-4/grammar-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册语法总结 · 过去分词作后置定语至独立主格的主语与分词","link":"/life/english/new-concept/book-4/grammar-part-03"},"next":{"text":"第四册：流利英语 · 全册语法总结 · there be 与存在命题至决策段落中的 however、therefore 与条件","link":"/life/english/new-concept/book-4/grammar-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-4/grammar-part-04.md","filePath":"life/english/new-concept/book-4/grammar-part-04.md"}'),r={name:"life/english/new-concept/book-4/grammar-part-04.md"};function s(i,e,l,h,p,c){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-全册语法总结-·-形容词前置的-as-让步结构至被动语态中的时态与体" tabindex="-1">第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体 <a class="header-anchor" href="#第四册-流利英语-·-全册语法总结-·-形容词前置的-as-让步结构至被动语态中的时态与体" aria-label="Permalink to &quot;第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="形容词前置的-as-让步结构" tabindex="-1">形容词前置的 as 让步结构 <a class="header-anchor" href="#形容词前置的-as-让步结构" aria-label="Permalink to &quot;形容词前置的 as 让步结构 {#形容词前置的-as-让步结构}&quot;">​</a></h2><p>形容词 + as + 主语 + be 可表示“尽管”，如 Limited as the evidence is, it deserves attention。它不同于表示原因的 As the evidence is limited…，语序和逻辑都不同。名词前置也可表让步，单数名词常不带冠词，如 Child as he was…；这种结构较正式。让步只承认前项，不取消后面的主句，但主句仍需独立理由支持，不能借修辞替代证据。</p><p><strong>L32 原创例句：</strong> Limited as the evidence is, it gives us a reason to repeat the experiment.</p><p>尽管证据有限，它仍给了我们重复实验的理由。</p><p><strong>易错：</strong> As the evidence is limited 通常更容易读成“因为证据有限”；要保留让步意思可用 Although 或前置 Limited as。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-032">Lesson 32</a></p><h2 id="平行结构与-not-only-but-also" tabindex="-1">平行结构与 not only…but also <a class="header-anchor" href="#平行结构与-not-only-but-also" aria-label="Permalink to &quot;平行结构与 not only…but also {#平行结构与-not-only-but-also}&quot;">​</a></h2><p>由 and、or、not only…but also 连接的成分应在语法层级上平行，例如 to question, to compare and to explain，不能混成 to question, comparing and an explanation。not only 放句首引出完整分句时，该分句要部分倒装；放在谓语内部连接宾语时一般不倒装。平行不只关乎词形，也要求项目处于同一逻辑类别，避免把学习行为与资源条件无说明地混列。</p><p><strong>L33 原创例句：</strong> The course teaches students to question claims, compare sources and explain their conclusions.</p><p>这门课程教学生质疑主张、比较来源并解释结论。</p><p><strong>易错：</strong> to question claims, comparing sources and explanations 不平行；应统一为三个动词短语。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-033">Lesson 33</a></p><h2 id="倾向表达与概率范围" tabindex="-1">倾向表达与概率范围 <a class="header-anchor" href="#倾向表达与概率范围" aria-label="Permalink to &quot;倾向表达与概率范围 {#倾向表达与概率范围}&quot;">​</a></h2><p>tend to do 描述常见倾向，不表示每次或所有人都如此；be likely to do 表示某情况发生的可能性较大，但不是必然。may 与 might 也能降低确定程度。Young people tend to seek… 仍是群体概括，应说明语境或证据来源。避免 tend to always 这类常常相互抵触的范围搭配；若只观察到某个学生，应保留单数对象而不要扩展成整个年龄群体。</p><p><strong>L34 原创例句：</strong> In this club, new members tend to ask their peers for help before approaching an adult.</p><p>在这个俱乐部里，新成员往往先向同伴求助，再找成年人。</p><p><strong>易错：</strong> tend to 不等于 always；不能将示例改写成“所有青少年都只向同伴求助”。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-034">Lesson 34</a></p><h2 id="将来完成时与未来截止点" tabindex="-1">将来完成时与未来截止点 <a class="header-anchor" href="#将来完成时与未来截止点" aria-label="Permalink to &quot;将来完成时与未来截止点 {#将来完成时与未来截止点}&quot;">​</a></h2><p>will have done 表示到某个未来时间点为止预计已经完成的动作，常与 by Friday、by the time…搭配。它不同于 will be doing，后者表示届时正在进行。by the time 引导未来时间从句时通常用一般现在时。计划文本中的 will have completed 是预测或承诺，并不是完成事实；若条件尚不确定，可用 may have completed 或明确加入 if 从句。</p><p><strong>L35 原创例句：</strong> By the time the simulated crew arrives, the support team will have checked every system.</p><p>到模拟机组到达时，支援团队将已检查完所有系统。</p><p><strong>易错：</strong> by the time the crew will arrive 不用于普通未来时间从句；应使用 arrives。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-035">Lesson 35</a></p><h2 id="倍数比较与百分比基数" tabindex="-1">倍数比较与百分比基数 <a class="header-anchor" href="#倍数比较与百分比基数" aria-label="Permalink to &quot;倍数比较与百分比基数 {#倍数比较与百分比基数}&quot;">​</a></h2><p>twice as much as 比较不可数数量，twice as many as 比较可数名词；three times the cost of… 也可表达倍数。increase by 20% 表增加幅度，increase to 20% 表达到的水平，两者不能互换。占比从 20% 到 30% 是增加 10 个百分点，相对原占比增加 50%。使用百分比必须给基数或可恢复的语境，否则读者可能把预算份额与绝对金额混淆。</p><p><strong>L36 原创例句：</strong> In the fictional budget, maintenance costs rose from 100 units to 120 units, an increase of 20%.</p><p>在虚构预算中，维护费从100单位升至120单位，增幅为20%。</p><p><strong>易错：</strong> rose by 120 units 不等于 rose to 120 units；本例只增加20单位。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-036">Lesson 36</a></p><h2 id="比较级重复与渐变表达" tabindex="-1">比较级重复与渐变表达 <a class="header-anchor" href="#比较级重复与渐变表达" aria-label="Permalink to &quot;比较级重复与渐变表达 {#比较级重复与渐变表达}&quot;">​</a></h2><p>形容词比较级 + and + 比较级表示越来越，如 slower and slower；多音节形容词用 more and more complex，不写 more complex and complex。increasingly + 形容词可作较紧凑表达。该结构只给出变化方向，不给变化速度、起点或适用范围。讨论群体研究时应补充 in this sample、over five years 等限定；趋势不意味着所有个体同步变化。</p><p><strong>L37 原创例句：</strong> The records became more and more detailed over the course of the study.</p><p>研究过程中，记录变得越来越详细。</p><p><strong>易错：</strong> more and more better 不成立；better 已是比较级，应写 better and better。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-037">Lesson 37</a></p><h2 id="if、when-后的省略结构" tabindex="-1">if、when 后的省略结构 <a class="header-anchor" href="#if、when-后的省略结构" aria-label="Permalink to &quot;if、when 后的省略结构 {#if、when-后的省略结构}&quot;">​</a></h2><p>if necessary、when available、if properly stored 等是条件或时间从句的压缩形式。if properly labelled 通常可展开为 if it is properly labelled，但被省略的主语必须能从主句或语境恢复。若前后主语不同，省略可能造成歧义。When travelling, check… 中 travelling 的执行者是祈使句隐含的 you；不能把同一短语接到 water is… 前，造成水在旅行的错误。</p><p><strong>L38 原创例句：</strong> When travelling, check current local guidance rather than rely on an old account.</p><p>旅行时，应核查当前当地指导信息，而不是依赖一篇旧记述。</p><p><strong>易错：</strong> When travelling, the water… 容易把 travelling 的执行者错接成 water；应明确人作主语。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-038">Lesson 38</a></p><h2 id="wish-后的时态与非现实意义" tabindex="-1">wish 后的时态与非现实意义 <a class="header-anchor" href="#wish-后的时态与非现实意义" aria-label="Permalink to &quot;wish 后的时态与非现实意义 {#wish-后的时态与非现实意义}&quot;">​</a></h2><p>wish + 一般过去时常表示对现在不满意而希望不同，如 I wish the ending were clearer。wish + had done 表示对过去的遗憾；wish + would do 常表达希望某人或某事改变，不能随意替代自己的可控计划。be 在较正式非现实表达中常用 were。希望未来有可能实现的结果通常用 hope；I hope readers will respond 与 I wish readers responded 的现实距离不同。</p><p><strong>L39 原创例句：</strong> I wish the opening were shorter, because the main point arrives too late.</p><p>我希望开头短一些，因为重点出现得太晚。</p><p><strong>易错：</strong> 不要把对现有稿件的遗憾写成 wish the opening is shorter；此处需要过去形式表达非现实。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-039">Lesson 39</a></p><h2 id="where-的地点与条件意义" tabindex="-1">where 的地点与条件意义 <a class="header-anchor" href="#where-的地点与条件意义" aria-label="Permalink to &quot;where 的地点与条件意义 {#where-的地点与条件意义}&quot;">​</a></h2><p>where 可以引导地点从句，也可在正式论述中表示“在……情况下”。Where the surface is uneven, the pattern becomes harder to interpret. 既可指表面不平的区域，也可泛指这种条件；语境决定侧重点。不能把 where 任意代替 when：时间应优先用 when，明确假设可用 if。关系从句中的 where 相当于 in/at which，只有先行词和介词关系合理时才可转换。</p><p><strong>L40 原创例句：</strong> Where the water meets the barrier, the pattern changes.</p><p>在水与障碍物相接的地方，波纹形态发生变化。</p><p><strong>易错：</strong> 不要把“实验结束时”写成 where the experiment ends；普通时间关系应写 when the experiment ends。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-040">Lesson 40</a></p><h2 id="with-宾语-补足语" tabindex="-1">with + 宾语 + 补足语 <a class="header-anchor" href="#with-宾语-补足语" aria-label="Permalink to &quot;with + 宾语 + 补足语 {#with-宾语-补足语}&quot;">​</a></h2><p>with 复合结构可用名词加形容词、介词短语、现在分词、过去分词或不定式补充背景。with the gate open 表状态；with the trainer watching 表主动进行；with the task completed 表被动或完成。选择分词要看宾语与动作的关系，而不是主句主语。它只是组织信息的方式，并不自动说明因果；需要明确原因时，完整 because 从句更准确。</p><p><strong>L41 原创例句：</strong> With the observer standing at a distance, the handler recorded the animal’s response.</p><p>观察者站在远处时，照管人员记录了动物的反应。</p><p><strong>易错：</strong> with the observer stood… 不能把一般过去时直接放入该结构；此处应用 standing。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-041">Lesson 41</a></p><h2 id="被动语态中的时态与体" tabindex="-1">被动语态中的时态与体 <a class="header-anchor" href="#被动语态中的时态与体" aria-label="Permalink to &quot;被动语态中的时态与体 {#被动语态中的时态与体}&quot;">​</a></h2><p>was recorded 表过去一次记录；has been recorded 强调到现在已有记录；is being recorded 表此刻正在记录；had been recorded 表早于另一个过去节点。被动结构的时态由 be 承担，过去分词 recorded 保持不变。不要把 has recorded 与 has been recorded 混淆，前者要求主语是记录者。选择时态时先确定时间参照，再决定是否需要完成或进行含义。</p><p><strong>L42 原创例句：</strong> The signal has been recorded, but the data are still being analysed.</p><p>信号已经记录下来，但数据仍在分析中。</p><p><strong>易错：</strong> The signal has recorded 错把信号当记录者；应使用 has been recorded。</p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-042">Lesson 42</a></p>',69)])])}const m=a(r,[["render",s]]);export{g as __pageData,m as default};
